import { expect, test } from "bun:test";

import { checkFixtureContract, fixtureFamilyId } from "../src/contract.ts";

test("fixtureFamilyId mirrors familyIdForRoot", () => {
  expect(fixtureFamilyId({ kind: "issue", number: 379 })).toBe("fam-379");
  expect(fixtureFamilyId({ kind: "operator_bundle", id: "kapitsa-fixture-contract" })).toBe(
    "fam-op-kapitsa-fixture-contract",
  );
  expect(fixtureFamilyId({ kind: "synthetic", id: "fixture-contract" })).toBe(
    "fam-syn-fixture-contract",
  );
});

test("checkFixtureContract accepts a consistent issue fixture", () => {
  expect(
    checkFixtureContract({
      family_id: "fam-379",
      root: { kind: "issue", number: 379 },
      reconstructs: null,
      failure_type: "missed_commit",
      synthetic: false,
    }),
  ).toEqual({ ok: true, problems: [] });
});

test("checkFixtureContract flags a family mismatch", () => {
  const out = checkFixtureContract({
    family_id: "fam-999",
    root: { kind: "issue", number: 379 },
    reconstructs: null,
    failure_type: "missed_commit",
    synthetic: false,
  });
  expect(out.ok).toBe(false);
  expect(out.problems).toContain("family_id_mismatch");
});
